fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 1536);
        host::display::state_set(2, 384);
    }
    let mut r: i32 = host::display::state_get(1);
    let mut f: i32 = host::display::state_get(2);
    let rf: i32 = (r * f) >> 8;
    let dr: i32 = (r * 2 - rf) / 64;
    let df: i32 = (rf - f * 4) / 128;
    r = r + dr;
    f = f + df;
    if r < 64 { r = 64; }
    if r > 8192 { r = 8192; }
    if f < 64 { f = 64; }
    if f > 8192 { f = 8192; }
    host::display::state_set(1, r);
    host::display::state_set(2, f);
    if t % 12 == 0 {
        let head: i32 = host::display::state_get(3);
        host::display::state_set(16 + head * 2, r);
        host::display::state_set(17 + head * 2, f);
        host::display::state_set(3, (head + 1) % 8);
    }
    host::display::clear(0x0c100c);
    host::display::draw_string(20, 20, "RABBITS", 0x60c060, 1);
    host::display::fill_rect(20, 34, r / 16, 12, 0x40a040);
    host::display::draw_number(20 + r / 16 + 8, 32, r / 16, 0xffffff, 1);
    host::display::draw_string(20, 60, "FOXES", 0xd08040, 1);
    host::display::fill_rect(20, 74, f / 16, 12, 0xc06020);
    host::display::draw_number(20 + f / 16 + 8, 72, f / 16, 0xffffff, 1);
    let bx: i32 = w - 220;
    let by: i32 = h - 220;
    host::display::fill_rect(bx, by, 200, 200, 0x141a14);
    let mut i: i32 = 0;
    while i < 8 {
        let pr: i32 = host::display::state_get(16 + i * 2);
        let pf: i32 = host::display::state_get(17 + i * 2);
        if pr > 0 {
            host::display::fill_rect(bx + pr / 48, by + 196 - pf / 48, 3, 3, 0x506050);
        }
        i = i + 1;
    }
    host::display::fill_rect(bx + r / 48 - 2, by + 196 - f / 48 - 2, 5, 5, 0xffffff);
    host::display::draw_string(bx, by - 16, "PHASE ORBIT", 0x606060, 1);
    host::display::present();
}
